class MsnStore extends ChangeNotifier {
  static const key='msn_manager_v2';
  final Map<String,dynamic> data={};
  List<dynamic> list(String k)=>(data[k] as List?) ?? <dynamic>[];
  List<Map<String,dynamic>> maps(String k)=>list(k).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();
  Future<void> init() async {
    final p=await SharedPreferences.getInstance();
    final raw=p.getString(key);
    if(raw!=null){
      try{ data.addAll(Map<String,dynamic>.from(jsonDecode(raw))); }
      catch(_){ await loadSeed(); }
    } else { await loadSeed(); }
    normalize();
    await save();
  }
  Future<void> loadSeed() async {
    data.clear();
    final raw=await rootBundle.loadString('assets/data/msn_seed.json');
    data.addAll(Map<String,dynamic>.from(jsonDecode(raw)));
  }
  void normalize(){
    for(final k in ['users','clients','services','commands','quotes','invoices','tasks','notifications','portfolio','templates','messages','files','receptions','activity','presentations']){
      if(data[k] is! List)data[k]=[];
    }
    if(data['workflows'] is! Map)data['workflows']={};
    if(data['prefs'] is! Map)data['prefs']={'notif':true,'sound':false,'language':'fr'};
    if(data['sync'] is! Map)data['sync']={'onlineEndpoint':'','onlineEnabled':false,'bluetoothEnabled':false,'lastSync':null};
    if(data['docSettings'] is! Map)data['docSettings']={};
  }
  Future<void> save() async {
    normalize();
    final p=await SharedPreferences.getInstance();
    await p.setString(key,jsonEncode(data));
    notifyListeners();
  }
  Future<void> reset() async { await loadSeed(); normalize(); await save(); }
  Map<String,dynamic> client(String id)=>maps('clients').firstWhere((x)=>x['id']==id,orElse:()=>{'id':id,'name':'Client inconnu','phone':''});
  Map<String,dynamic>? byId(String collection,String id){ for(final x in maps(collection)){if(x['id']==id)return x;} return null; }
  Map<String,dynamic>? command(String id)=>byId('commands',id);
  String nextId(String prefix,String collection){ final n=maps(collection).length+1; return '$prefix-${n.toString().padLeft(4,'0')}'; }
}

class SessionManager {
  static const key='msn_session_v2';
  static Future<Map<String,dynamic>?> load() async { final p=await SharedPreferences.getInstance(); final raw=p.getString(key); if(raw==null)return null; try{return Map<String,dynamic>.from(jsonDecode(raw));}catch(_){return null;} }
  static Future<void> save(Map<String,dynamic> s) async { final p=await SharedPreferences.getInstance(); await p.setString(key,jsonEncode(s)); }
  static Future<void> clear() async { final p=await SharedPreferences.getInstance(); await p.remove(key); }
}
String hashPassword(String value)=>sha256.convert(utf8.encode(value)).toString();

class SyncService {
  final MsnStore store;
  SyncService(this.store);
  Future<String> pushOnline() async {
    final endpoint='${store.data['sync']?['onlineEndpoint']??''}'.trim();
    if(endpoint.isEmpty) throw Exception('Configurez l’URL de synchronisation en ligne.');
    final r=await http.post(Uri.parse(endpoint),headers:{'content-type':'application/json'},body:jsonEncode({'version':2,'device':'android','data':store.data}));
    if(r.statusCode<200||r.statusCode>=300)throw Exception('Serveur: HTTP ${r.statusCode}');
    store.data['sync']['lastSync']=DateTime.now().toIso8601String(); await store.save(); return 'Synchronisation en ligne terminée';
  }
  Future<String> pullOnline() async {
    final endpoint='${store.data['sync']?['onlineEndpoint']??''}'.trim();
    if(endpoint.isEmpty) throw Exception('Configurez l’URL de synchronisation en ligne.');
    final r=await http.get(Uri.parse(endpoint));
    if(r.statusCode<200||r.statusCode>=300)throw Exception('Serveur: HTTP ${r.statusCode}');
    final decoded=Map<String,dynamic>.from(jsonDecode(r.body)); final incoming=decoded['data'] is Map?Map<String,dynamic>.from(decoded['data']):decoded;
    for(final e in incoming.entries){store.data[e.key]=e.value;}
    store.normalize(); store.data['sync']['lastSync']=DateTime.now().toIso8601String(); await store.save(); return 'Données en ligne importées';
  }
  Future<List<BluetoothDevice>> scan() async { if(!await FlutterBluePlus.isSupported) throw Exception('Bluetooth LE non supporté sur cet appareil.'); await Permission.bluetoothScan.request(); await Permission.bluetoothConnect.request(); if(await Permission.bluetoothScan.isDenied) throw Exception('Autorisation Bluetooth refusée.'); final found=<String,BluetoothDevice>{}; final sub=FlutterBluePlus.scanResults.listen((results){for(final r in results){found[r.device.remoteId.str]=r.device;}}); await FlutterBluePlus.startScan(timeout:const Duration(seconds:5)); await Future.delayed(const Duration(seconds:5)); await FlutterBluePlus.stopScan(); await sub.cancel(); return found.values.toList(); }
  Future<void> pushCommandsBluetooth(BluetoothDevice device) async { await Permission.bluetoothConnect.request(); await device.connect(timeout:const Duration(seconds:10),autoConnect:false); try { final services=await device.discoverServices(); BluetoothCharacteristic? target; for(final svc in services){for(final ch in svc.characteristics){if(ch.properties.write||ch.properties.writeWithoutResponse){target=ch;break;}} if(target!=null)break;} if(target==null)throw Exception('Aucune caractéristique BLE inscriptible trouvée sur le PC.'); final payload=utf8.encode('MSN2|COMMANDS|${base64Encode(utf8.encode(jsonEncode(store.maps('commands'))))}'); const chunk=180; for(int i=0;i<payload.length;i+=chunk){final end=i+chunk<payload.length?i+chunk:payload.length; await target!.write(payload.sublist(i,end),withoutResponse:target.properties.writeWithoutResponse);} } finally {await device.disconnect();} }
}

