class CollectionTools {
  static Future<void> exportItems(BuildContext context,MsnStore store,String collection,List<String> ids) async {
    final items=store.maps(collection).where((x)=>ids.isEmpty||ids.contains('${x['id']}')).toList();
    final dir=await getTemporaryDirectory(); final file=File('${dir.path}/msn_${collection}_export.json');
    await file.writeAsString(const JsonEncoder.withIndent('  ').convert({'collection':collection,'exportedAt':DateTime.now().toIso8601String(),'items':items}));
    await Share.shareXFiles([XFile(file.path)],text:'Export MSN Manager — $collection (${items.length})');
  }
  static Future<void> importItems(BuildContext context,MsnStore store,String collection) async {
    try {
      final result=await FilePicker.platform.pickFiles(type:FileType.custom,allowedExtensions:['json'],withData:true);
      if(result==null)return;
      final bytes=result.files.single.bytes; if(bytes==null)throw Exception('Fichier illisible');
      final raw=utf8.decode(bytes); final decoded=jsonDecode(raw); final incoming=(decoded is Map&&decoded['items'] is List)?decoded['items']:decoded;
      if(incoming is! List)throw Exception('Format JSON invalide');
      final current=store.maps(collection); final byId={for(final x in current)'${x['id']}':x};
      for(final rawItem in incoming){if(rawItem is Map){final item=Map<String,dynamic>.from(rawItem);final id='${item['id']??''}';if(id.isEmpty)continue;byId[id]=item;}}
      store.data[collection]=byId.values.toList(); await store.save();
      if(context.mounted)snack(context,'${byId.length} élément(s) disponible(s) dans $collection');
    }catch(e){if(context.mounted)snack(context,'Import impossible : $e');}
  }
  static Future<void> deleteItems(BuildContext context,MsnStore store,String collection,List<String> ids) async {
    if(ids.isEmpty){snack(context,'Sélectionnez au moins un élément');return;}
    final ok=await confirm(context,'Supprimer','Supprimer ${ids.length} élément(s) ? Cette action est irréversible.');if(!ok)return;
    final set=ids.toSet();store.data[collection]=store.maps(collection).where((x)=>!set.contains('${x['id']}')).toList();await store.save();snack(context,'Suppression effectuée');
  }
}

