void showQuote(BuildContext c,MsnStore s,Map<String,dynamic> q){final cl=s.client(q['client']);showModalBottomSheet(context:c,isScrollControlled:true,showDragHandle:true,builder:(_)=>Padding(padding:const EdgeInsets.all(18),child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('${q['id']} — DEVIS',style:const TextStyle(fontSize:20,fontWeight:FontWeight.w900)),Text(cl['name']),Text(q['service']),const Divider(),...(q['lines'] as List).map((l)=>ListTile(title:Text(l['d']),subtitle:Text('${l['q']} × ${money(l['pu'])}'),trailing:Text(money((l['q'] as num)*(l['pu'] as num))))),Text('TOTAL : ${money(q['amount'])}',style:const TextStyle(fontSize:18,fontWeight:FontWeight.w900)),const SizedBox(height:12),FilledButton.icon(onPressed:()async{await Share.share(quoteText(q,cl));},icon:const Icon(Icons.share),label:const Text('Partager'))]))));}
String quoteText(Map<String,dynamic> q,Map<String,dynamic> cl)=>'MSN — MULTI-SERVICES NUMÉRIQUES\nDEVIS ${q['id']}\nClient: ${cl['name']}\nService: ${q['service']}\nTotal: ${money(q['amount'])}';
class QuoteForm extends StatefulWidget{final MsnStore store;const QuoteForm({super.key,required this.store});@override State<QuoteForm> createState()=>_QuoteFormState();}
class _QuoteFormState extends State<QuoteForm>{String? client,service;final qty=TextEditingController(text:'1'),pu=TextEditingController(text:'0');@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Nouveau devis')),body:ListView(padding:const EdgeInsets.all(18),children:[DropdownButtonFormField<String>(value:client,decoration:const InputDecoration(labelText:'Client *'),items:widget.store.maps('clients').map((x)=>DropdownMenuItem(value:x['id'] as String,child:Text(x['name']))).toList(),onChanged:(v)=>setState(()=>client=v)),DropdownButtonFormField<String>(value:service,decoration:const InputDecoration(labelText:'Service *'),items:storeServices(widget.store).map((x)=>DropdownMenuItem(value:x['name'] as String,child:Text(x['name']))).toList(),onChanged:(v){setState(()=>service=v);final s=servicesByName(widget.store,v??'');pu.text='${s?['base']??0}';}),const SizedBox(height:12),TextField(controller:qty,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Quantité',border:OutlineInputBorder())),const SizedBox(height:12),TextField(controller:pu,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Prix unitaire',border:OutlineInputBorder())),const SizedBox(height:18),FilledButton(onPressed:save,child:const Text('Créer le devis'))]));void save(){if(client==null||service==null){snack(context,'Client et service requis');return;}final q=(num.tryParse(qty.text)??1)*(num.tryParse(pu.text)??0);if(q<=0){snack(context,'Montant invalide');return;}final qs=widget.store.maps('quotes');final id='DEV-${2406+qs.length}';qs.insert(0,{'id':id,'client':client,'service':service,'status':'brouillon','date':dateStr(DateTime.now()),'valid':dateStr(DateTime.now().add(const Duration(days:14))),'amount':q,'lines':[{'d':service,'q':num.tryParse(qty.text)??1,'pu':num.tryParse(pu.text)??0}]});widget.store.data['quotes']=qs;widget.store.save();Navigator.pop(context);snack(context,'Devis créé');}}

class Invoices extends StatelessWidget{final MsnStore store;const Invoices({super.key,required this.store});@override Widget build(BuildContext c)=>SelectableCollectionPage(store:store,collection:'invoices',title:'Factures',icon:Icons.receipt_long,itemTitle:(i)=>'${i['id']} · ${store.client('${i['client']}')['name']}',itemSubtitle:(i){final rest=((i['amount']??0) as num)-((i['paid']??0) as num);return '${i['service']} · ${money((i['amount']??0) as num)} · reste ${money(rest)} · ${statusLabel(i['status'])}';},onOpen:(ctx,i)=>showInvoice(ctx,store,i));}

void showInvoice(BuildContext c,MsnStore s,Map<String,dynamic> i){final cl=s.client(i['client']);showModalBottomSheet(context:c,showDragHandle:true,builder:(_)=>Padding(padding:const EdgeInsets.all(18),child(Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text('${i['id']} — FACTURE',style:const TextStyle(fontSize:20,fontWeight:FontWeight.w900)),Text(cl['name']),Text(i['service']),const Divider(),Text('Total : ${money(i['amount'])}'),Text('Payé : ${money(i['paid'])}'),Text('Reste : ${money((i['amount'] as num)-(i['paid'] as num))}'),const Spacer(),FilledButton(onPressed:(){i['paid']=i['amount'];i['status']='payee';s.save();Navigator.pop(c);snack(c,'Facture payée');},child:const Text('Marquer comme payée'))])));}

class Tasks extends StatelessWidget{final MsnStore store;const Tasks({super.key,required this.store});@override Widget build(BuildContext c)=>SelectableCollectionPage(store:store,collection:'tasks',title:'Tâches',icon:Icons.task_alt,itemTitle:(t)=>'${t['title']}',itemSubtitle:(t)=>'${t['cmd']??''} · ${deadlineLabel('${t['due']??''}')} · ${t['priority']} · ${t['status']}',onAdd:()=>showTaskDialog(c,store),onOpen:(ctx,t)=>showTaskEditDialog(ctx,store,t));}


void showGenericMap(BuildContext c,String title,Map<String,dynamic> item){showModalBottomSheet(context:c,isScrollControlled:true,showDragHandle:true,builder:(_)=>Padding(padding:const EdgeInsets.all(18),child:SingleChildScrollView(child:Column(crossAxisAlignment:CrossAxisAlignment.stretch,children:[Text(title,style:const TextStyle(fontSize:20,fontWeight:FontWeight.w900)),const SizedBox(height:12),...item.entries.map((e)=>Padding(padding:const EdgeInsets.only(bottom:8),child:Text('${e.key}: ${e.value}')))]))));}
void showTaskEditDialog(BuildContext c,MsnStore s,Map<String,dynamic> t){final title=TextEditingController(text:'${t['title']??''}');String status='${t['status']??'todo'}';showDialog(context:c,builder:(_)=>StatefulBuilder(builder:(ctx,set)=>AlertDialog(title:const Text('Modifier la tâche'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Intitulé')),DropdownButtonFormField<String>(value:status,items:['todo','inprogress','done'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>set(()=>status=v!))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:const Text('Annuler')),FilledButton(onPressed:(){t['title']=title.text.trim();t['status']=status;s.save();Navigator.pop(ctx);},child:const Text('Enregistrer'))])));}
void showServiceDialog(BuildContext c,MsnStore s,Map<String,dynamic> x){final price=TextEditingController(text:'${x['base']??0}');final desc=TextEditingController(text:'${x['desc']??''}');showDialog(context:c,builder:(_)=>AlertDialog(title:Text('${x['name']}'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:price,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Tarif')),TextField(controller:desc,maxLines:3,decoration:const InputDecoration(labelText:'Description'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Annuler')),FilledButton(onPressed:(){x['base']=num.tryParse(price.text)??0;x['desc']=desc.text;s.save();Navigator.pop(c);},child:const Text('Enregistrer'))]));}
void showPortfolioDialog(BuildContext c,MsnStore s,Map<String,dynamic> x){showGenericMap(c,'Réalisation',x);}
void showFileDialog(BuildContext c,MsnStore s,Map<String,dynamic> x){showGenericMap(c,'Fichier',x);}
void openNotificationTarget(BuildContext c,MsnStore s,Map<String,dynamic> n){final text='${n['text']??''}';final cmd=RegExp(r'CMD-\d+').firstMatch(text)?.group(0);if(cmd!=null){Navigator.push(c,MaterialPageRoute(builder:(_)=>WorkflowPage(store:s,commandId:cmd)));return;}if(text.toLowerCase().contains('whatsapp'))openExternalChannel(c,'WhatsApp','whatsapp://send?text=${Uri.encodeComponent(text)}','https://wa.me/?text=${Uri.encodeComponent(text)}');else if(text.toLowerCase().contains('messenger'))openExternalChannel(c,'Messenger','fb-messenger://','https://m.me/');else openExternalChannel(c,'WhatsApp','whatsapp://send?text=${Uri.encodeComponent(text)}','https://wa.me/?text=${Uri.encodeComponent(text)}');}
Future<void> openExternalChannel(BuildContext c,String name,String appUrl,String webUrl) async {try{final app=Uri.parse(appUrl);if(await canLaunchUrl(app)){await launchUrl(app,mode:LaunchMode.externalApplication);return;}final web=Uri.parse(webUrl);if(await canLaunchUrl(web)){await launchUrl(web,mode:LaunchMode.externalApplication);return;}snack(c,'$name n’est pas disponible sur cet appareil.');}catch(e){snack(c,'Impossible d’ouvrir $name : $e');}}
Future<void> changePassword(BuildContext c,MsnStore s,String username) async {final old=TextEditingController(),nw=TextEditingController(),confirmPw=TextEditingController();final user=s.maps('users').firstWhere((x)=>x['username']==username);await showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('Changer le mot de passe'),content:SingleChildScrollView(child:Column(children:[TextField(controller:old,obscureText:true,decoration:const InputDecoration(labelText:'Mot de passe actuel')),TextField(controller:nw,obscureText:true,decoration:const InputDecoration(labelText:'Nouveau mot de passe')),TextField(controller:confirmPw,obscureText:true,decoration:const InputDecoration(labelText:'Confirmer le nouveau mot de passe'))])),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Annuler')),FilledButton(onPressed:()async{if(hashPassword(old.text)!=user['passwordHash']&&old.text!=user['password']){snack(c,'Mot de passe actuel incorrect');return;}if(nw.text.length<6||nw.text!=confirmPw.text){snack(c,'Le nouveau mot de passe doit contenir au moins 6 caractères et être confirmé');return;}user.remove('password');user['passwordHash']=hashPassword(nw.text);await s.save();Navigator.pop(c);snack(c,'Mot de passe modifié');},child:const Text('Enregistrer'))]));}
void showTaskDialog(BuildContext c,MsnStore s){final title=TextEditingController();showDialog(context:c,builder:(_)=>AlertDialog(title:const Text('Nouvelle tâche'),content:TextField(controller:title,decoration:const InputDecoration(labelText:'Intitulé')),actions:[TextButton(onPressed:()=>Navigator.pop(c),child:const Text('Annuler')),FilledButton(onPressed:(){if(title.text.trim().isEmpty)return;final ts=s.maps('tasks');ts.insert(0,{'id':'T-${ts.length+1}','title':title.text.trim(),'cmd':'','priority':'moyenne','due':dateStr(DateTime.now()),'status':'todo'});s.data['tasks']=ts;s.save();Navigator.pop(c);},child:const Text('Créer'))]));}

